<template><view class="page"><text class="title">我的未来职业探索清单</text><view v-for="item in items" :key="item.careerId" class="item"><text>{{item.careerName}}</text><button v-if="!readOnly" size="mini" @click="remove(item)">删除</button></view><text class="count">{{items.length}} / 6</text><button v-if="!readOnly" type="primary" @click="finish">确认探索并下载 PDF</button><button v-else type="primary" @click="download">下载 PDF</button></view></template>
<script>import{getExploration,removeExplorationItem,finishRecord,downloadReportPdf,userMessage}from'@/api/zycck';export default{data:()=>({recordId:'',instanceId:'',gameId:'',items:[],readOnly:false}),onLoad(o){Object.assign(this,{recordId:o.recordId||'',instanceId:o.instanceId||'',gameId:o.gameId||'',readOnly:o.readOnly==='1'});this.load()},methods:{async load(){try{const r=await getExploration(this.recordId);const d=r.data||{};this.items=d.items||d.explorationItems||[]}catch(e){uni.showToast({title:userMessage(e,'探索清单加载失败，请重试'),icon:'none'})}},async remove(i){if(this.readOnly)return;try{await removeExplorationItem(this.recordId,i.careerId);this.load()}catch(e){uni.showToast({title:userMessage(e,'移除清单失败，请重试'),icon:'none'})}},async finish(){if(this.readOnly)return;try{await finishRecord(this.recordId);this.readOnly=true;uni.showToast({title:'探索已完成',icon:'success'});this.download()}catch(e){uni.showToast({title:userMessage(e,'请先查看至少一个职业'),icon:'none'})}},async download(){try{uni.showLoading({title:'生成 PDF'});const r=await downloadReportPdf({recordId:this.recordId});const path=r.tempFilePath||r.filePath;if(path)uni.openDocument({filePath:path,showMenu:true,fileType:'pdf'});else throw new Error('PDF 下载失败')}catch(e){uni.showToast({title:userMessage(e,'PDF 下载失败，请稍后重试'),icon:'none'})}finally{uni.hideLoading()}}}}</script>
<style scoped>.page{padding:48rpx 36rpx;background:#f5f7fb;min-height:100vh;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center}.title{display:block;font-size:42rpx;font-weight:700;margin-bottom:30rpx;text-align:center}.item{display:flex;justify-content:space-between;align-items:center;background:#fff;padding:24rpx;margin:12rpx 0;border-radius:14rpx;box-shadow:0 6rpx 18rpx rgba(31,41,55,.04)}.count{display:block;text-align:right;color:#64748b;margin:20rpx 0}</style>
